import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { once } from 'node:events';
import { readFile, writeFile } from 'node:fs/promises';
import Papa from 'papaparse';

const cases = JSON.parse(await readFile(process.env.EVALUATION_INPUT, 'utf8'));
const observations = [];
const server = createServer(async (request, response) => {
  try {
    const chunks = [];
    for await (const chunk of request) chunks.push(chunk);
    const { csv } = JSON.parse(Buffer.concat(chunks).toString());
    const result = Papa.parse(csv, { header: true, skipEmptyLines: true });
    response.writeHead(200, { 'content-type': 'application/json' });
    response.end(JSON.stringify(result));
  } catch (error) {
    response.writeHead(400, { 'content-type': 'application/json' });
    response.end(JSON.stringify({ error: error.message }));
  }
});
server.listen(0, '127.0.0.1');
await once(server, 'listening');
try {
  for (const item of cases) {
    const response = await fetch(`http://127.0.0.1:${server.address().port}/parse`, {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ csv: item.csv }),
    });
    const actual = await response.json();
    const observation = { name: item.name, input: item.csv, expected: item.expected, actual: actual.data, errors: actual.errors, status: response.status };
    observations.push(observation);
    assert.equal(response.status, 200);
    assert.deepEqual(actual.errors, []);
    assert.deepEqual(actual.data, item.expected);
  }
} finally {
  server.closeAllConnections();
  await new Promise((resolve) => server.close(resolve));
  await writeFile(process.env.EVALUATION_RESULTS, JSON.stringify({ cases_run: observations.length, observations }, null, 2));
  await writeFile(`${process.env.EVALUATION_ARTIFACTS}/http-observations.json`, JSON.stringify(observations, null, 2));
}
